Ui.Script:
XmlMethodBindingProbeLog = {
    siblingMutation = {},
    setScriptObjectTable = {},
}

local function summarizeValue(value)
    return {
        type = type(value),
        tostring = tostring(value),
    }
end

local function protectedCall(fn)
    local ok, result = pcall(fn)
    if ok then
        return {
            ok = true,
            value = summarizeValue(result),
        }
    end
    return {
        ok = false,
        error = tostring(result),
    }
end

function XmlMethodBindingProbeSnapshotScriptState(frame, label)
    local getScriptResult = protectedCall(function()
        return frame:GetScript("OnHide")
    end)
    local fieldResult = protectedCall(function()
        return frame.OnHide
    end)
    local rawgetResult = protectedCall(function()
        return rawget(frame, "OnHide")
    end)
    local pairsResult = protectedCall(function()
        local keys = {}
        for key in pairs(frame) do
            table.insert(keys, tostring(key))
        end
        table.sort(keys)
        return table.concat(keys, ",")
    end)
    local equalResult = protectedCall(function()
        return frame:GetScript("OnHide") == frame.OnHide
    end)
    XmlMethodBindingProbeLog.setScriptObjectTable[#XmlMethodBindingProbeLog.setScriptObjectTable + 1] = {
        label = label,
        getScript = getScriptResult,
        field = fieldResult,
        rawget = rawgetResult,
        pairs = pairsResult,
        getScriptEqualsField = equalResult,
    }
end

local function record(caseName, value)
    XmlMethodBindingProbeLog[caseName] = XmlMethodBindingProbeLog[caseName] or {}
    table.insert(XmlMethodBindingProbeLog[caseName], value)
end

XmlMethodBindingProbeHideMixin = {}
function XmlMethodBindingProbeHideMixin:OnHide()
    record("siblingMutation", "hide1")
end

function XmlMethodBindingProbeBaseFoo(self)
    XmlMethodBindingProbeLog.inheritedMethod = "base"
end

function XmlMethodBindingProbeOverrideFoo(self)
    XmlMethodBindingProbeLog.inheritedMethod = "override"
end

function XmlMethodBindingProbeTextBaseFoo(self)
    XmlMethodBindingProbeLog.inheritedScriptText = "base"
end

function XmlMethodBindingProbeTextOverrideFoo(self)
    XmlMethodBindingProbeLog.inheritedScriptText = "override"
end
